    CallAnalyticsJob.add_member(:call_analytics_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobName, location_name: 'CallAnalyticsJobName', traits: {"smithy.api#documentation" => "<p>The name of the Call Analytics job. Job names are case sensitive and must be unique\n            within an Amazon Web Services account.</p>"}))
    CallAnalyticsJob.add_member(:call_analytics_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobStatus, location_name: 'CallAnalyticsJobStatus', traits: {"smithy.api#documentation" => "<p>Provides the status of the specified Call Analytics job.</p>\n         <p>If the status is <code>COMPLETED</code>, the job is finished and you can find the\n            results at the location specified in <code>TranscriptFileUri</code> (or\n                <code>RedactedTranscriptFileUri</code>, if you requested transcript redaction). If\n            the status is <code>FAILED</code>, <code>FailureReason</code> provides details on why\n            your transcription job failed.</p>"}))
    CallAnalyticsJob.add_member(:call_analytics_job_details, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobDetails, location_name: 'CallAnalyticsJobDetails', traits: {"smithy.api#documentation" => "<p>Provides detailed information about a call analytics job, including information about skipped analytics features.</p>"}))
    CallAnalyticsJob.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code used to create your Call Analytics job. For a list of supported\n            languages and their associated language codes, refer to the <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/supported-languages.html\">Supported languages</a>\n            table.</p>\n         <p>If you do not know the language spoken in your media file, you can omit this field and\n            let Amazon Transcribe automatically identify the language of your media. To improve the\n            accuracy of language identification, you can include several language codes and Amazon Transcribe chooses the closest match for your transcription.</p>"}))
    CallAnalyticsJob.add_member(:media_sample_rate_hertz, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaSampleRateHertz, location_name: 'MediaSampleRateHertz', traits: {"smithy.api#documentation" => "<p>The sample rate, in hertz, of the audio track in your input media file.</p>"}))
    CallAnalyticsJob.add_member(:media_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaFormat, location_name: 'MediaFormat', traits: {"smithy.api#documentation" => "<p>The format of the input media file.</p>"}))
    CallAnalyticsJob.add_member(:media, Smithy::Schema::Shapes::ShapeRef.new(shape: Media, location_name: 'Media', traits: {"smithy.api#documentation" => "<p>Provides the Amazon S3 location of the media file you used in your Call\n            Analytics request.</p>"}))
    CallAnalyticsJob.add_member(:transcript, Smithy::Schema::Shapes::ShapeRef.new(shape: Transcript, location_name: 'Transcript'))
    CallAnalyticsJob.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics job began processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.789000-07:00</code> represents a transcription job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJob.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics job request was made.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.761000-07:00</code> represents a transcription job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJob.add_member(:completion_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CompletionTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics job finished processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:33:13.922000-07:00</code> represents a transcription job\n            that started processing at 12:33 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJob.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If <code>CallAnalyticsJobStatus</code> is <code>FAILED</code>,\n                <code>FailureReason</code> contains information about why the Call Analytics job\n            request failed.</p>\n         <p>The <code>FailureReason</code> field contains one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Unsupported media format</code>.</p>\n               <p>The media format specified in <code>MediaFormat</code> isn't valid. Refer to\n                    refer to the <code>MediaFormat</code> parameter for a list of supported\n                    formats.</p>\n            </li>\n            <li>\n               <p>\n                  <code>The media format provided does not match the detected media\n                        format</code>.</p>\n               <p>The media format specified in <code>MediaFormat</code> doesn't match the\n                    format of the input file. Check the media format of your media file and correct\n                    the specified value.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Invalid sample rate for audio file</code>.</p>\n               <p>The sample rate specified in <code>MediaSampleRateHertz</code> isn't valid.\n                    The sample rate must be between 8,000 and 48,000 hertz.</p>\n            </li>\n            <li>\n               <p>\n                  <code>The sample rate provided does not match the detected sample\n                    rate</code>.</p>\n               <p>The sample rate specified in <code>MediaSampleRateHertz</code> doesn't match\n                    the sample rate detected in your input media file. Check the sample rate of your\n                    media file and correct the specified value.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Invalid file size: file size too large</code>.</p>\n               <p>The size of your media file is larger than what Amazon Transcribe can\n                    process. For more information, refer to <a href=\"https://docs.aws.amazon.com/general/latest/gr/transcribe.html#limits-amazon-transcribe\">Service \n                        quotas</a>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Invalid number of channels: number of channels too large</code>.</p>\n               <p>Your audio contains more channels than Amazon Transcribe is able to process.\n                    For more information, refer to <a href=\"https://docs.aws.amazon.com/general/latest/gr/transcribe.html#limits-amazon-transcribe\">Service \n                        quotas</a>.</p>\n            </li>\n         </ul>"}))
    CallAnalyticsJob.add_member(:data_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: DataAccessRoleArn, location_name: 'DataAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) you included in your request.</p>"}))
    CallAnalyticsJob.add_member(:identified_language_score, Smithy::Schema::Shapes::ShapeRef.new(shape: IdentifiedLanguageScore, location_name: 'IdentifiedLanguageScore', traits: {"smithy.api#documentation" => "<p>The confidence score associated with the language identified in your media\n            file.</p>\n         <p>Confidence scores are values between 0 and 1; a larger value indicates a higher\n            probability that the identified language correctly matches the language spoken in your\n            media.</p>"}))
    CallAnalyticsJob.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobSettings, location_name: 'Settings', traits: {"smithy.api#documentation" => "<p>Provides information on any additional settings that were included in your request.\n            Additional settings include content redaction and language identification\n            settings.</p>"}))
