    CallAnalyticsJobSummary.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics job request was made.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.761000-07:00</code> represents a transcription job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJobSummary.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time your Call Analytics job began processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.789000-07:00</code> represents a transcription job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJobSummary.add_member(:completion_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CompletionTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics job finished processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:33:13.922000-07:00</code> represents a transcription job\n            that started processing at 12:33 PM UTC-7 on May 4, 2022.</p>"}))
    CallAnalyticsJobSummary.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code used to create your Call Analytics transcription.</p>"}))
    CallAnalyticsJobSummary.add_member(:call_analytics_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobStatus, location_name: 'CallAnalyticsJobStatus', traits: {"smithy.api#documentation" => "<p>Provides the status of your Call Analytics job.</p>\n         <p>If the status is <code>COMPLETED</code>, the job is finished and you can find the\n            results at the location specified in <code>TranscriptFileUri</code> (or\n                <code>RedactedTranscriptFileUri</code>, if you requested transcript redaction). If\n            the status is <code>FAILED</code>, <code>FailureReason</code> provides details on why\n            your transcription job failed.</p>"}))
    CallAnalyticsJobSummary.add_member(:call_analytics_job_details, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobDetails, location_name: 'CallAnalyticsJobDetails', traits: {"smithy.api#documentation" => "<p>Provides detailed information about a call analytics job, including information about skipped analytics features.</p>"}))
    CallAnalyticsJobSummary.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If <code>CallAnalyticsJobStatus</code> is <code>FAILED</code>,\n                <code>FailureReason</code> contains information about why the Call Analytics job\n            failed. See also: <a href=\"https://docs.aws.amazon.com/transcribe/latest/APIReference/CommonErrors.html\">Common Errors</a>.</p>"}))
