    CallAnalyticsSkippedFeature.add_member(:reason_code, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsSkippedReasonCode, location_name: 'ReasonCode', traits: {"smithy.api#documentation" => "<p>Provides a code indicating the reason why a specific analytics feature was skipped during the analysis of a call analytics job.</p>"}))
    CallAnalyticsSkippedFeature.add_member(:message, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Message', traits: {"smithy.api#documentation" => "<p>Contains additional information or a message explaining why a specific analytics feature was skipped during the analysis of a call analytics job.</p>"}))
