    CategoryProperties.add_member(:category_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CategoryName, location_name: 'CategoryName', traits: {"smithy.api#documentation" => "<p>The name of the Call Analytics category. Category names are case sensitive and must be\n            unique within an Amazon Web Services account.</p>"}))
    CategoryProperties.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleList, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>The rules used to define a Call Analytics category. Each category can have between 1\n            and 20 rules.</p>"}))
