    CategoryProperties.add_member(:last_update_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'LastUpdateTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Call Analytics category was last updated.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-05T12:45:32.691000-07:00</code> represents 12:45 PM UTC-7 on May\n            5, 2022.</p>"}))
    CategoryProperties.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags, each in the form of a key:value pair, assigned to the specified\n            call analytics category.</p>"}))
    CategoryProperties.add_member(:input_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InputType, location_name: 'InputType', traits: {"smithy.api#documentation" => "<p>The input type associated with the specified category. <code>POST_CALL</code> \n            refers to a category that is applied to batch transcriptions; <code>REAL_TIME</code> \n            refers to a category that is applied to streaming transcriptions.</p>"}))
