    ContentRedaction.add_member(:redaction_type, Smithy::Schema::Shapes::ShapeRef.new(shape: RedactionType, location_name: 'RedactionType', traits: {"smithy.api#documentation" => "<p>Specify the category of information you want to redact; <code>PII</code> (personally\n            identifiable information) is the only valid value. You can use <code>PiiEntityTypes</code> to \n            choose which types of PII you want to redact. If you do not include <code>PiiEntityTypes</code> in \n            your request, all PII is redacted.</p>", "smithy.api#required" => {}}))
    ContentRedaction.add_member(:redaction_output, Smithy::Schema::Shapes::ShapeRef.new(shape: RedactionOutput, location_name: 'RedactionOutput', traits: {"smithy.api#documentation" => "<p>Specify if you want only a redacted transcript, or if you want a redacted and an\n            unredacted transcript.</p>\n         <p>When you choose <code>redacted</code>\n            Amazon Transcribe creates only a redacted transcript.</p>\n         <p>When you choose <code>redacted_and_unredacted</code>\n            Amazon Transcribe creates a redacted and an unredacted transcript (as two separate\n            files).</p>", "smithy.api#required" => {}}))
    ContentRedaction.add_member(:pii_entity_types, Smithy::Schema::Shapes::ShapeRef.new(shape: PiiEntityTypes, location_name: 'PiiEntityTypes', traits: {"smithy.api#documentation" => "<p>Specify which types of personally identifiable information (PII) you want to redact in\n            your transcript. You can include as many types as you'd like, or you can select\n            <code>ALL</code>. If you do not include <code>PiiEntityTypes</code> in your request, all PII is \n            redacted.</p>"}))
    ContentRedaction.type = Types::ContentRedaction
    CreateCallAnalyticsCategoryRequest.add_member(:category_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CategoryName, location_name: 'CategoryName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your Call Analytics category. It's helpful to use a\n            detailed naming system that will make sense to you in the future. For example, it's\n            better to use <code>sentiment-positive-last30seconds</code> for a category over a\n            generic name like <code>test-category</code>.</p>\n         <p>Category names are case sensitive.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CreateCallAnalyticsCategoryRequest.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleList, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>Rules define a Call Analytics category. When creating a new category, you must create \n            between 1 and 20 rules for that category. For each rule, you specify a filter you want \n            applied to the attributes of a call. For example, you can choose a sentiment filter that \n            detects if a customer's sentiment was positive during the last 30 seconds of the call.</p>", "smithy.api#required" => {}}))
    CreateCallAnalyticsCategoryRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new\n            call analytics category at the time you start this new job.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n            resources</a>.</p>"}))
    CreateCallAnalyticsCategoryRequest.add_member(:input_type, Smithy::Schema::Shapes::ShapeRef.new(shape: InputType, location_name: 'InputType', traits: {"smithy.api#documentation" => "<p>Choose whether you want to create a real-time or a post-call category for your Call \n            Analytics transcription.</p>\n         <p>Specifying <code>POST_CALL</code> assigns your category to post-call transcriptions; \n            categories with this input type cannot be applied to streaming (real-time) \n            transcriptions.</p>\n         <p>Specifying <code>REAL_TIME</code> assigns your category to streaming transcriptions; \n            categories with this input type cannot be applied to post-call transcriptions.</p>\n         <p>If you do not include <code>InputType</code>, your category is created as a post-call \n            category by default.</p>"}))
    CreateCallAnalyticsCategoryRequest.type = Types::CreateCallAnalyticsCategoryRequest
    CreateCallAnalyticsCategoryResponse.add_member(:category_properties, Smithy::Schema::Shapes::ShapeRef.new(shape: CategoryProperties, location_name: 'CategoryProperties', traits: {"smithy.api#documentation" => "<p>Provides you with the properties of your new category, including its associated\n            rules.</p>"}))
    CreateCallAnalyticsCategoryResponse.type = Types::CreateCallAnalyticsCategoryResponse
    CreateLanguageModelRequest.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: CLMLanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code that represents the language of your model. Each custom language\n            model must contain terms in only one language, and the language you select for your\n            custom language model must match the language of your training and tuning data.</p>\n         <p>For a list of supported languages and their associated language codes, refer to the\n                <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/supported-languages.html\">Supported languages</a> table. Note that US English (<code>en-US</code>) is the \n            only language supported with Amazon Transcribe Medical.</p>\n         <p>A custom language model can only be used to transcribe files in the same language as\n            the model. For example, if you create a custom language model using US English\n                (<code>en-US</code>), you can only apply this model to files that contain English\n            audio.</p>", "smithy.api#required" => {}}))
    CreateLanguageModelRequest.add_member(:base_model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BaseModelName, location_name: 'BaseModelName', traits: {"smithy.api#documentation" => "<p>The Amazon Transcribe standard language model, or base model, used to create your\n            custom language model. Amazon Transcribe offers two options for base models: Wideband\n            and Narrowband.</p>\n         <p>If the audio you want to transcribe has a sample rate of 16,000 Hz or greater, choose\n                <code>WideBand</code>. To transcribe audio with a sample rate less than 16,000 Hz,\n            choose <code>NarrowBand</code>.</p>", "smithy.api#required" => {}}))
    CreateLanguageModelRequest.add_member(:model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelName, location_name: 'ModelName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your custom language model.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new custom language model with\n            the same name as an existing custom language model, you get a\n                <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CreateLanguageModelRequest.add_member(:input_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDataConfig, location_name: 'InputDataConfig', traits: {"smithy.api#documentation" => "<p>Contains the Amazon S3 location of the training data you want to use to create\n            a new custom language model, and permissions to access this location.</p>\n         <p>When using <code>InputDataConfig</code>, you must include these sub-parameters:\n                <code>S3Uri</code>, which is the Amazon S3 location of your training data,\n            and <code>DataAccessRoleArn</code>, which is the Amazon Resource Name (ARN) of the role\n            that has permission to access your specified Amazon S3 location. You can\n            optionally include <code>TuningDataS3Uri</code>, which is the Amazon S3 location\n            of your tuning data. If you specify different Amazon S3 locations for training\n            and tuning data, the ARN you use must have permissions to access both locations.</p>", "smithy.api#required" => {}}))
    CreateLanguageModelRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new custom\n            language model at the time you create this new model.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n                resources</a>.</p>"}))
    CreateLanguageModelRequest.type = Types::CreateLanguageModelRequest
    CreateLanguageModelResponse.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: CLMLanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code you selected for your custom language model.</p>"}))
    CreateLanguageModelResponse.add_member(:base_model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: BaseModelName, location_name: 'BaseModelName', traits: {"smithy.api#documentation" => "<p>The Amazon Transcribe standard language model, or base model, you specified when\n            creating your custom language model.</p>"}))
    CreateLanguageModelResponse.add_member(:model_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelName, location_name: 'ModelName', traits: {"smithy.api#documentation" => "<p>The name of your custom language model.</p>"}))
