    CreateLanguageModelResponse.add_member(:model_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelStatus, location_name: 'ModelStatus', traits: {"smithy.api#documentation" => "<p>The status of your custom language model. When the status displays as\n                <code>COMPLETED</code>, your model is ready to use.</p>"}))
    CreateLanguageModelResponse.type = Types::CreateLanguageModelResponse
    CreateMedicalVocabularyRequest.add_member(:vocabulary_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyName, location_name: 'VocabularyName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your new custom medical vocabulary.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new custom medical vocabulary\n            with the same name as an existing custom medical vocabulary, you get a\n                <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    CreateMedicalVocabularyRequest.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code that represents the language of the entries in your custom\n            vocabulary. US English (<code>en-US</code>) is the only language supported with Amazon Transcribe Medical.</p>", "smithy.api#required" => {}}))
    CreateMedicalVocabularyRequest.add_member(:vocabulary_file_uri, Smithy::Schema::Shapes::ShapeRef.new(shape: Uri, location_name: 'VocabularyFileUri', traits: {"smithy.api#documentation" => "<p>The Amazon S3 location (URI) of the text file that contains your custom\n            medical vocabulary. The URI must be in the same Amazon Web Services Region as the\n            resource you're calling.</p>\n         <p>Here's an example URI path:\n            <code>s3://DOC-EXAMPLE-BUCKET/my-vocab-file.txt</code>\n         </p>", "smithy.api#required" => {}}))
    CreateMedicalVocabularyRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new custom\n            medical vocabulary at the time you create this new custom vocabulary.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n                resources</a>.</p>"}))
