    CreateVocabularyFilterRequest.add_member(:vocabulary_filter_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterName, location_name: 'VocabularyFilterName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your new custom vocabulary filter.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new custom vocabulary filter with\n            the same name as an existing custom vocabulary filter, you get a\n                <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
