    MedicalScribeJobSummary.add_member(:creation_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CreationTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Medical Scribe job request was made.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.761000-07:00</code> represents a Medical Scribe job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    MedicalScribeJobSummary.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time your Medical Scribe job began processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.789000-07:00</code> represents a Medical Scribe job\n            that started processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    MedicalScribeJobSummary.add_member(:completion_time, Smithy::Schema::Shapes::ShapeRef.new(shape: DateTime, location_name: 'CompletionTime', traits: {"smithy.api#documentation" => "<p>The date and time the specified Medical Scribe job finished processing.</p>\n         <p>Timestamps are in the format <code>YYYY-MM-DD'T'HH:MM:SS.SSSSSS-UTC</code>. For\n            example, <code>2022-05-04T12:32:58.761000-07:00</code> represents a Medical Scribe job\n            that finished processing at 12:32 PM UTC-7 on May 4, 2022.</p>"}))
    MedicalScribeJobSummary.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeLanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code used to create your Medical Scribe job. US English\n                (<code>en-US</code>) is the only supported language for Medical Scribe jobs. </p>"}))
    MedicalScribeJobSummary.add_member(:medical_scribe_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeJobStatus, location_name: 'MedicalScribeJobStatus', traits: {"smithy.api#documentation" => "<p>Provides the status of the specified Medical Scribe job.</p>\n         <p>If the status is <code>COMPLETED</code>, the job is finished and you can find the\n            results at the location specified in <code>MedicalScribeOutput</code> If\n            the status is <code>FAILED</code>, <code>FailureReason</code> provides details on why\n            your Medical Scribe job failed.</p>"}))
    MedicalScribeJobSummary.add_member(:failure_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: FailureReason, location_name: 'FailureReason', traits: {"smithy.api#documentation" => "<p>If <code>MedicalScribeJobStatus</code> is <code>FAILED</code>,\n            <code>FailureReason</code> contains information about why the transcription job\n            failed. See also: <a href=\"https://docs.aws.amazon.com/transcribe/latest/APIReference/CommonErrors.html\">Common Errors</a>.</p>"}))
