    MedicalScribeSettings.add_member(:show_speaker_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ShowSpeakerLabels', traits: {"smithy.api#documentation" => "<p>Enables speaker partitioning (diarization) in your Medical Scribe output. Speaker\n            partitioning labels the speech from individual speakers in your media file.</p>\n         <p>If you enable <code>ShowSpeakerLabels</code> in your request, you must also include\n                <code>MaxSpeakerLabels</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/diarization.html\">Partitioning speakers\n                (diarization)</a>.</p>"}))
    MedicalScribeSettings.add_member(:max_speaker_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxSpeakers, location_name: 'MaxSpeakerLabels', traits: {"smithy.api#documentation" => "<p>Specify the maximum number of speakers you want to partition in your media.</p>\n         <p>Note that if your media contains more speakers than the specified number, multiple\n            speakers are treated as a single speaker.</p>\n         <p>If you specify the <code>MaxSpeakerLabels</code> field, you must set the\n                <code>ShowSpeakerLabels</code> field to true.</p>"}))
    MedicalScribeSettings.add_member(:channel_identification, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ChannelIdentification', traits: {"smithy.api#documentation" => "<p>Enables channel identification in multi-channel audio.</p>\n         <p>Channel identification transcribes the audio on each channel independently, then\n            appends the output for each channel into one transcript.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/channel-id.html\">Transcribing multi-channel\n            audio</a>.</p>"}))
    MedicalScribeSettings.add_member(:vocabulary_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyName, location_name: 'VocabularyName', traits: {"smithy.api#documentation" => "<p>The name of the custom vocabulary you want to include in your Medical Scribe\n            request. Custom vocabulary names are case sensitive.</p>"}))
    MedicalScribeSettings.add_member(:vocabulary_filter_name, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterName, location_name: 'VocabularyFilterName', traits: {"smithy.api#documentation" => "<p>The name of the custom vocabulary filter you want to include in your Medical Scribe\n            request. Custom vocabulary filter names are case sensitive.</p>\n         <p>Note that if you include <code>VocabularyFilterName</code> in your request, you must\n            also include <code>VocabularyFilterMethod</code>.</p>"}))
    MedicalScribeSettings.add_member(:vocabulary_filter_method, Smithy::Schema::Shapes::ShapeRef.new(shape: VocabularyFilterMethod, location_name: 'VocabularyFilterMethod', traits: {"smithy.api#documentation" => "<p>Specify how you want your custom vocabulary filter applied to your transcript.</p>\n         <p>To replace words with <code>***</code>, choose <code>mask</code>.</p>\n         <p>To delete words, choose <code>remove</code>.</p>\n         <p>To flag words without changing them, choose <code>tag</code>.</p>"}))
    MedicalScribeSettings.add_member(:clinical_note_generation_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ClinicalNoteGenerationSettings, location_name: 'ClinicalNoteGenerationSettings', traits: {"smithy.api#documentation" => "<p>Specify settings for the clinical note generation.</p>"}))
