    MedicalTranscriptionJob.add_member(:transcription_job_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TranscriptionJobStatus, location_name: 'TranscriptionJobStatus', traits: {"smithy.api#documentation" => "<p>Provides the status of the specified medical transcription job.</p>\n         <p>If the status is <code>COMPLETED</code>, the job is finished and you can find the\n            results at the location specified in <code>TranscriptFileUri</code>. If the status is\n                <code>FAILED</code>, <code>FailureReason</code> provides details on why your\n            transcription job failed.</p>"}))
