    MedicalTranscriptionJob.add_member(:media_sample_rate_hertz, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalMediaSampleRateHertz, location_name: 'MediaSampleRateHertz', traits: {"smithy.api#documentation" => "<p>The sample rate, in hertz, of the audio track in your input media file.</p>"}))
