    StartCallAnalyticsJobRequest.add_member(:call_analytics_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobName, location_name: 'CallAnalyticsJobName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your Call Analytics job.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new job with the same name as an\n            existing job, you get a <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
