    StartCallAnalyticsJobRequest.add_member(:output_location, Smithy::Schema::Shapes::ShapeRef.new(shape: Uri, location_name: 'OutputLocation', traits: {"smithy.api#documentation" => "<p>The Amazon S3 location where you want your Call Analytics transcription output\n            stored. You can use any of the following formats to specify the output location:</p>\n         <ol>\n            <li>\n               <p>s3://DOC-EXAMPLE-BUCKET</p>\n            </li>\n            <li>\n               <p>s3://DOC-EXAMPLE-BUCKET/my-output-folder/</p>\n            </li>\n            <li>\n               <p>s3://DOC-EXAMPLE-BUCKET/my-output-folder/my-call-analytics-job.json</p>\n            </li>\n         </ol>\n         <p>Unless you specify a file name (option 3), the name of your output file has a default\n            value that matches the name you specified for your transcription job using the\n                <code>CallAnalyticsJobName</code> parameter.</p>\n         <p>You can specify a KMS key to encrypt your output using the\n                <code>OutputEncryptionKMSKeyId</code> parameter. If you do not specify a KMS key, Amazon Transcribe uses the default Amazon S3 key for\n            server-side encryption.</p>\n         <p>If you do not specify <code>OutputLocation</code>, your transcript is placed in a\n            service-managed Amazon S3 bucket and you are provided with a URI to access your\n            transcript.</p>"}))
    StartCallAnalyticsJobRequest.add_member(:output_encryption_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSKeyId, location_name: 'OutputEncryptionKMSKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key you want to use to encrypt your Call Analytics\n            output.</p>\n         <p>If using a key located in the <b>current</b>\n            Amazon Web Services account, you can specify your KMS key in one of four\n            ways:</p>\n         <ol>\n            <li>\n               <p>Use the KMS key ID itself. For example,\n                        <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use an alias for the KMS key ID. For example,\n                        <code>alias/ExampleAlias</code>.</p>\n            </li>\n            <li>\n               <p>Use the Amazon Resource Name (ARN) for the KMS key ID. For\n                    example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If using a key located in a <b>different</b>\n            Amazon Web Services account than the current Amazon Web Services account, you can specify\n            your KMS key in one of two ways:</p>\n         <ol>\n            <li>\n               <p>Use the ARN for the KMS key ID. For example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If you do not specify an encryption key, your output is encrypted with the default\n                Amazon S3 key (SSE-S3).</p>\n         <p>If you specify a KMS key to encrypt your output, you must also specify\n            an output location using the <code>OutputLocation</code> parameter.</p>\n         <p>Note that the role making the  request must\n            have permission to use the specified KMS key.</p>"}))
    StartCallAnalyticsJobRequest.add_member(:data_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: DataAccessRoleArn, location_name: 'DataAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an IAM role that has permissions to\n            access the Amazon S3 bucket that contains your input files. If the role that you\n            specify doesn’t have the appropriate permissions to access the specified Amazon S3 location, your request fails.</p>\n         <p>IAM role ARNs have the format\n            <code>arn:partition:iam::account:role/role-name-with-path</code>. For example:\n            <code>arn:aws:iam::111122223333:role/Admin</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_identifiers.html#identifiers-arns\">IAM\n            ARNs</a>.</p>"}))
    StartCallAnalyticsJobRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJobSettings, location_name: 'Settings', traits: {"smithy.api#documentation" => "<p>Specify additional optional settings in your  request, including content redaction; allows you to apply custom language models,\n            vocabulary filters, and custom vocabularies to your Call Analytics job.</p>"}))
    StartCallAnalyticsJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new\n            call analytics job at the time you start this new job.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n            resources</a>.</p>"}))
    StartCallAnalyticsJobRequest.add_member(:channel_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: ChannelDefinitions, location_name: 'ChannelDefinitions', traits: {"smithy.api#documentation" => "<p>Makes it possible to specify which speaker is on which channel. For example, if your\n            agent is the first participant to speak, you would set <code>ChannelId</code> to\n                <code>0</code> (to indicate the first channel) and <code>ParticipantRole</code> to\n                <code>AGENT</code> (to indicate that it's the agent speaking).</p>"}))
    StartCallAnalyticsJobRequest.type = Types::StartCallAnalyticsJobRequest
    StartCallAnalyticsJobResponse.add_member(:call_analytics_job, Smithy::Schema::Shapes::ShapeRef.new(shape: CallAnalyticsJob, location_name: 'CallAnalyticsJob', traits: {"smithy.api#documentation" => "<p>Provides detailed information about the current Call Analytics job, including job\n            status and, if applicable, failure reason.</p>"}))
    StartCallAnalyticsJobResponse.type = Types::StartCallAnalyticsJobResponse
    StartMedicalScribeJobRequest.add_member(:medical_scribe_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TranscriptionJobName, location_name: 'MedicalScribeJobName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your Medical Scribe job.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new job with the same name as an\n            existing job, you get a <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    StartMedicalScribeJobRequest.add_member(:media, Smithy::Schema::Shapes::ShapeRef.new(shape: Media, location_name: 'Media', traits: {"smithy.api#required" => {}}))
    StartMedicalScribeJobRequest.add_member(:output_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputBucketName, location_name: 'OutputBucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket where you want your Medical Scribe\n            output stored. Do not include the <code>S3://</code> prefix of the specified\n            bucket.</p>\n         <p>Note that the role specified in the <code>DataAccessRoleArn</code> request parameter \n            must have permission to use the specified location. You\n            can change Amazon S3 permissions using the <a href=\"https://console.aws.amazon.com/s3\">Amazon Web Services Management Console</a>. See also <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/security_iam_id-based-policy-examples.html#auth-role-iam-user\">Permissions Required for IAM User Roles</a>.</p>", "smithy.api#required" => {}}))
    StartMedicalScribeJobRequest.add_member(:output_encryption_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSKeyId, location_name: 'OutputEncryptionKMSKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key you want to use to encrypt your Medical Scribe\n            output.</p>\n         <p>If using a key located in the <b>current</b>\n            Amazon Web Services account, you can specify your KMS key in one of four\n            ways:</p>\n         <ol>\n            <li>\n               <p>Use the KMS key ID itself. For example,\n                        <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use an alias for the KMS key ID. For example,\n                        <code>alias/ExampleAlias</code>.</p>\n            </li>\n            <li>\n               <p>Use the Amazon Resource Name (ARN) for the KMS key ID. For\n                    example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If using a key located in a <b>different</b>\n            Amazon Web Services account than the current Amazon Web Services account, you can specify\n            your KMS key in one of two ways:</p>\n         <ol>\n            <li>\n               <p>Use the ARN for the KMS key ID. For example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If you do not specify an encryption key, your output is encrypted with the default\n                Amazon S3 key (SSE-S3).</p>\n         <p>Note that the role specified in the <code>DataAccessRoleArn</code> request parameter \n            must have permission to use the specified KMS key.</p>"}))
    StartMedicalScribeJobRequest.add_member(:kms_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSEncryptionContextMap, location_name: 'KMSEncryptionContext', traits: {"smithy.api#documentation" => "<p>A map of plain text, non-secret key:value pairs, known as encryption context pairs,\n            that provide an added layer of security for your data. For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/key-management.html#kms-context\">KMS encryption context</a> and <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/symmetric-asymmetric.html\">Asymmetric keys in KMS</a>.</p>"}))
    StartMedicalScribeJobRequest.add_member(:data_access_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: DataAccessRoleArn, location_name: 'DataAccessRoleArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of an IAM role that has permissions to\n            access the Amazon S3 bucket that contains your input files, \n            write to the output bucket, and use your KMS key if supplied.  \n             If the role that you specify doesn’t have the appropriate permissions your request fails.</p>\n         <p>IAM role ARNs have the format\n            <code>arn:partition:iam::account:role/role-name-with-path</code>. For example:\n            <code>arn:aws:iam::111122223333:role/Admin</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_identifiers.html#identifiers-arns\">IAM\n            ARNs</a>.</p>", "smithy.api#required" => {}}))
    StartMedicalScribeJobRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeSettings, location_name: 'Settings', traits: {"smithy.api#documentation" => "<p>Makes it possible to control how your Medical Scribe job is processed using a\n            <code>MedicalScribeSettings</code> object. Specify <code>ChannelIdentification</code> if \n            <code>ChannelDefinitions</code> are set. Enabled <code>ShowSpeakerLabels</code> if <code>ChannelIdentification</code> \n            and <code>ChannelDefinitions</code> are not set. One and only one of <code>ChannelIdentification</code> and <code>ShowSpeakerLabels</code>\n            must be set. If <code>ShowSpeakerLabels</code> is set, <code>MaxSpeakerLabels</code> must also be set. Use <code>Settings</code>\n            to specify a vocabulary or vocabulary filter or both using <code>VocabularyName</code>, <code>VocabularyFilterName</code>. \n            <code>VocabularyFilterMethod</code> must be specified if <code>VocabularyFilterName</code> is set.\n        </p>", "smithy.api#required" => {}}))
    StartMedicalScribeJobRequest.add_member(:channel_definitions, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeChannelDefinitions, location_name: 'ChannelDefinitions', traits: {"smithy.api#documentation" => "<p>Makes it possible to specify which speaker is on which channel. For example, if the clinician\n             is the first participant to speak, you would set <code>ChannelId</code> of the first <code>ChannelDefinition</code> \n             in the list to <code>0</code> (to indicate the first channel) and <code>ParticipantRole</code> to\n                <code>CLINICIAN</code> (to indicate that it's the clinician speaking).\n                Then you would set the <code>ChannelId</code> of the second <code>ChannelDefinition</code> in the list to\n                <code>1</code> (to indicate the second channel) and <code>ParticipantRole</code> to\n                <code>PATIENT</code> (to indicate that it's the patient speaking).\n                </p>"}))
    StartMedicalScribeJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to the Medical Scribe job.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n                resources</a>.</p>"}))
    StartMedicalScribeJobRequest.add_member(:medical_scribe_context, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeContext, location_name: 'MedicalScribeContext', traits: {"smithy.api#documentation" => "<p>The <code>MedicalScribeContext</code> object that contains contextual information which is used during\n            clinical note generation to add relevant context to the note.</p>"}))
    StartMedicalScribeJobRequest.type = Types::StartMedicalScribeJobRequest
    StartMedicalScribeJobResponse.add_member(:medical_scribe_job, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalScribeJob, location_name: 'MedicalScribeJob', traits: {"smithy.api#documentation" => "<p>Provides detailed information about the current Medical Scribe job, including\n            job status and, if applicable, failure reason.</p>"}))
    StartMedicalScribeJobResponse.type = Types::StartMedicalScribeJobResponse
    StartMedicalTranscriptionJobRequest.add_member(:medical_transcription_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TranscriptionJobName, location_name: 'MedicalTranscriptionJobName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your medical transcription job. The name that you\n            specify is also used as the default name of your transcription output file. If you want\n            to specify a different name for your transcription output, use the\n                <code>OutputKey</code> parameter.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new job with the same name as an\n            existing job, you get a <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code that represents the language spoken in the input media file. US\n            English (<code>en-US</code>) is the only valid value for medical transcription jobs. Any\n            other value you enter for language code results in a <code>BadRequestException</code>\n            error.</p>", "smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:media_sample_rate_hertz, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalMediaSampleRateHertz, location_name: 'MediaSampleRateHertz', traits: {"smithy.api#documentation" => "<p>The sample rate, in hertz, of the audio track in your input media file.</p>\n         <p>If you do not specify the media sample rate, Amazon Transcribe Medical determines it\n            for you. If you specify the sample rate, it must match the rate detected by Amazon Transcribe Medical; if there's a mismatch between the value that you specify and the\n            value detected, your job fails. Therefore, in most cases, it's advised to omit\n                <code>MediaSampleRateHertz</code> and let Amazon Transcribe Medical determine the\n            sample rate.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:media_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaFormat, location_name: 'MediaFormat', traits: {"smithy.api#documentation" => "<p>Specify the format of your input media file.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:media, Smithy::Schema::Shapes::ShapeRef.new(shape: Media, location_name: 'Media', traits: {"smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:output_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputBucketName, location_name: 'OutputBucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket where you want your medical transcription\n            output stored. Do not include the <code>S3://</code> prefix of the specified\n            bucket.</p>\n         <p>If you want your output to go to a sub-folder of this bucket, specify it using the\n                <code>OutputKey</code> parameter; <code>OutputBucketName</code> only accepts the\n            name of a bucket.</p>\n         <p>For example, if you want your output stored in <code>S3://DOC-EXAMPLE-BUCKET</code>,\n            set <code>OutputBucketName</code> to <code>DOC-EXAMPLE-BUCKET</code>. However, if you\n            want your output stored in <code>S3://DOC-EXAMPLE-BUCKET/test-files/</code>, set\n                <code>OutputBucketName</code> to <code>DOC-EXAMPLE-BUCKET</code> and\n                <code>OutputKey</code> to <code>test-files/</code>.</p>\n         <p>Note that Amazon Transcribe must have permission to use the specified location. You\n            can change Amazon S3 permissions using the <a href=\"https://console.aws.amazon.com/s3\">Amazon Web Services Management Console</a>. See also <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/security_iam_id-based-policy-examples.html#auth-role-iam-user\">Permissions Required for IAM User Roles</a>.</p>", "smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:output_key, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputKey, location_name: 'OutputKey', traits: {"smithy.api#documentation" => "<p>Use in combination with <code>OutputBucketName</code> to specify the output location\n            of your transcript and, optionally, a unique name for your output file. The default name\n            for your transcription output is the same as the name you specified for your medical\n            transcription job (<code>MedicalTranscriptionJobName</code>).</p>\n         <p>Here are some examples of how you can use <code>OutputKey</code>:</p>\n         <ul>\n            <li>\n               <p>If you specify 'DOC-EXAMPLE-BUCKET' as the <code>OutputBucketName</code> and\n                    'my-transcript.json' as the <code>OutputKey</code>, your transcription output\n                    path is <code>s3://DOC-EXAMPLE-BUCKET/my-transcript.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'my-first-transcription' as the\n                        <code>MedicalTranscriptionJobName</code>, 'DOC-EXAMPLE-BUCKET' as the\n                        <code>OutputBucketName</code>, and 'my-transcript' as the\n                        <code>OutputKey</code>, your transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/my-transcript/my-first-transcription.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'DOC-EXAMPLE-BUCKET' as the <code>OutputBucketName</code> and\n                    'test-files/my-transcript.json' as the <code>OutputKey</code>, your\n                    transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/test-files/my-transcript.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'my-first-transcription' as the\n                        <code>MedicalTranscriptionJobName</code>, 'DOC-EXAMPLE-BUCKET' as the\n                        <code>OutputBucketName</code>, and 'test-files/my-transcript' as the\n                        <code>OutputKey</code>, your transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/test-files/my-transcript/my-first-transcription.json</code>.</p>\n            </li>\n         </ul>\n         <p>If you specify the name of an Amazon S3 bucket sub-folder that doesn't exist,\n            one is created for you.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:output_encryption_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSKeyId, location_name: 'OutputEncryptionKMSKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key you want to use to encrypt your medical transcription\n            output.</p>\n         <p>If using a key located in the <b>current</b>\n            Amazon Web Services account, you can specify your KMS key in one of four\n            ways:</p>\n         <ol>\n            <li>\n               <p>Use the KMS key ID itself. For example,\n                        <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use an alias for the KMS key ID. For example,\n                        <code>alias/ExampleAlias</code>.</p>\n            </li>\n            <li>\n               <p>Use the Amazon Resource Name (ARN) for the KMS key ID. For\n                    example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If using a key located in a <b>different</b>\n            Amazon Web Services account than the current Amazon Web Services account, you can specify\n            your KMS key in one of two ways:</p>\n         <ol>\n            <li>\n               <p>Use the ARN for the KMS key ID. For example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If you do not specify an encryption key, your output is encrypted with the default\n                Amazon S3 key (SSE-S3).</p>\n         <p>If you specify a KMS key to encrypt your output, you must also specify\n            an output location using the <code>OutputLocation</code> parameter.</p>\n         <p>Note that the role making the  request must\n            have permission to use the specified KMS key.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:kms_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSEncryptionContextMap, location_name: 'KMSEncryptionContext', traits: {"smithy.api#documentation" => "<p>A map of plain text, non-secret key:value pairs, known as encryption context pairs,\n            that provide an added layer of security for your data. For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/key-management.html#kms-context\">KMS encryption context</a> and <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/symmetric-asymmetric.html\">Asymmetric keys in KMS</a>.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalTranscriptionSetting, location_name: 'Settings', traits: {"smithy.api#documentation" => "<p>Specify additional optional settings in your  request, including channel\n            identification, alternative transcriptions, and speaker partitioning. You can use that to\n            apply custom vocabularies to your transcription job.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:content_identification_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalContentIdentificationType, location_name: 'ContentIdentificationType', traits: {"smithy.api#documentation" => "<p>Labels all personal health information (PHI) identified in your transcript. For more\n            information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/phi-id.html\">Identifying personal health information (PHI) in a transcription</a>.</p>"}))
    StartMedicalTranscriptionJobRequest.add_member(:specialty, Smithy::Schema::Shapes::ShapeRef.new(shape: Specialty, location_name: 'Specialty', traits: {"smithy.api#documentation" => "<p>Specify the predominant medical specialty represented in your media. For batch\n            transcriptions, <code>PRIMARYCARE</code> is the only valid value. If you require\n            additional specialties, refer to .</p>", "smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: Type, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>Specify whether your input media contains only one person (<code>DICTATION</code>) or\n            contains a conversation between two people (<code>CONVERSATION</code>).</p>\n         <p>For example, <code>DICTATION</code> could be used for a medical professional wanting\n            to transcribe voice memos; <code>CONVERSATION</code> could be used for transcribing the\n            doctor-patient dialogue during the patient's office visit.</p>", "smithy.api#required" => {}}))
    StartMedicalTranscriptionJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new medical\n            transcription job at the time you start this new job.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n                resources</a>.</p>"}))
    StartMedicalTranscriptionJobRequest.type = Types::StartMedicalTranscriptionJobRequest
    StartMedicalTranscriptionJobResponse.add_member(:medical_transcription_job, Smithy::Schema::Shapes::ShapeRef.new(shape: MedicalTranscriptionJob, location_name: 'MedicalTranscriptionJob', traits: {"smithy.api#documentation" => "<p>Provides detailed information about the current medical transcription job, including\n            job status and, if applicable, failure reason.</p>"}))
    StartMedicalTranscriptionJobResponse.type = Types::StartMedicalTranscriptionJobResponse
    StartTranscriptionJobRequest.add_member(:transcription_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: TranscriptionJobName, location_name: 'TranscriptionJobName', traits: {"smithy.api#documentation" => "<p>A unique name, chosen by you, for your transcription job. The name that you specify is\n            also used as the default name of your transcription output file. If you want to specify\n            a different name for your transcription output, use the <code>OutputKey</code>\n            parameter.</p>\n         <p>This name is case sensitive, cannot contain spaces, and must be unique within an\n                Amazon Web Services account. If you try to create a new job with the same name as an\n            existing job, you get a <code>ConflictException</code> error.</p>", "smithy.api#httpLabel" => {}, "smithy.api#required" => {}}))
    StartTranscriptionJobRequest.add_member(:language_code, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageCode, location_name: 'LanguageCode', traits: {"smithy.api#documentation" => "<p>The language code that represents the language spoken in the input media file.</p>\n         <p>If you're unsure of the language spoken in your media file, consider using\n                <code>IdentifyLanguage</code> or <code>IdentifyMultipleLanguages</code> to enable\n            automatic language identification.</p>\n         <p>Note that you must include one of <code>LanguageCode</code>,\n                <code>IdentifyLanguage</code>, or <code>IdentifyMultipleLanguages</code> in your\n            request. If you include more than one of these parameters, your transcription job\n            fails.</p>\n         <p>For a list of supported languages and their associated language codes, refer to the\n                <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/supported-languages.html\">Supported languages</a> table.</p>\n         <note>\n            <p>To transcribe speech in Modern Standard Arabic (<code>ar-SA</code>) in Amazon Web Services GovCloud (US) (US-West, us-gov-west-1), Amazon Web Services GovCloud (US) (US-East, us-gov-east-1), Canada (Calgary, ca-west-1) and Africa (Cape Town, af-south-1), your media\n                file must be encoded at a sample rate of 16,000 Hz or higher.</p>\n         </note>"}))
    StartTranscriptionJobRequest.add_member(:media_sample_rate_hertz, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaSampleRateHertz, location_name: 'MediaSampleRateHertz', traits: {"smithy.api#documentation" => "<p>The sample rate, in hertz, of the audio track in your input media file.</p>\n         <p>If you do not specify the media sample rate, Amazon Transcribe determines it for you.\n            If you specify the sample rate, it must match the rate detected by Amazon Transcribe.\n            If there's a mismatch between the value that you specify and the value detected, your\n            job fails. In most cases, you can omit <code>MediaSampleRateHertz</code> and let Amazon Transcribe determine the sample rate.</p>"}))
    StartTranscriptionJobRequest.add_member(:media_format, Smithy::Schema::Shapes::ShapeRef.new(shape: MediaFormat, location_name: 'MediaFormat', traits: {"smithy.api#documentation" => "<p>Specify the format of your input media file.</p>"}))
    StartTranscriptionJobRequest.add_member(:media, Smithy::Schema::Shapes::ShapeRef.new(shape: Media, location_name: 'Media', traits: {"smithy.api#documentation" => "<p>Describes the Amazon S3 location of the media file you want to use in your\n            request.</p>", "smithy.api#required" => {}}))
    StartTranscriptionJobRequest.add_member(:output_bucket_name, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputBucketName, location_name: 'OutputBucketName', traits: {"smithy.api#documentation" => "<p>The name of the Amazon S3 bucket where you want your transcription output\n            stored. Do not include the <code>S3://</code> prefix of the specified bucket.</p>\n         <p>If you want your output to go to a sub-folder of this bucket, specify it using the\n                <code>OutputKey</code> parameter; <code>OutputBucketName</code> only accepts the\n            name of a bucket.</p>\n         <p>For example, if you want your output stored in <code>S3://DOC-EXAMPLE-BUCKET</code>,\n            set <code>OutputBucketName</code> to <code>DOC-EXAMPLE-BUCKET</code>. However, if you\n            want your output stored in <code>S3://DOC-EXAMPLE-BUCKET/test-files/</code>, set\n                <code>OutputBucketName</code> to <code>DOC-EXAMPLE-BUCKET</code> and\n                <code>OutputKey</code> to <code>test-files/</code>.</p>\n         <p>Note that Amazon Transcribe must have permission to use the specified location. You\n            can change Amazon S3 permissions using the <a href=\"https://console.aws.amazon.com/s3\">Amazon Web Services Management Console</a>. See also <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/security_iam_id-based-policy-examples.html#auth-role-iam-user\">Permissions Required for IAM User Roles</a>.</p>\n         <p>If you do not specify <code>OutputBucketName</code>, your transcript is placed in a\n            service-managed Amazon S3 bucket and you are provided with a URI to access your\n            transcript.</p>"}))
    StartTranscriptionJobRequest.add_member(:output_key, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputKey, location_name: 'OutputKey', traits: {"smithy.api#documentation" => "<p>Use in combination with <code>OutputBucketName</code> to specify the output location\n            of your transcript and, optionally, a unique name for your output file. The default name\n            for your transcription output is the same as the name you specified for your\n            transcription job (<code>TranscriptionJobName</code>).</p>\n         <p>Here are some examples of how you can use <code>OutputKey</code>:</p>\n         <ul>\n            <li>\n               <p>If you specify 'DOC-EXAMPLE-BUCKET' as the <code>OutputBucketName</code> and\n                    'my-transcript.json' as the <code>OutputKey</code>, your transcription output\n                    path is <code>s3://DOC-EXAMPLE-BUCKET/my-transcript.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'my-first-transcription' as the\n                        <code>TranscriptionJobName</code>, 'DOC-EXAMPLE-BUCKET' as the\n                        <code>OutputBucketName</code>, and 'my-transcript' as the\n                        <code>OutputKey</code>, your transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/my-transcript/my-first-transcription.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'DOC-EXAMPLE-BUCKET' as the <code>OutputBucketName</code> and\n                    'test-files/my-transcript.json' as the <code>OutputKey</code>, your\n                    transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/test-files/my-transcript.json</code>.</p>\n            </li>\n            <li>\n               <p>If you specify 'my-first-transcription' as the\n                        <code>TranscriptionJobName</code>, 'DOC-EXAMPLE-BUCKET' as the\n                        <code>OutputBucketName</code>, and 'test-files/my-transcript' as the\n                        <code>OutputKey</code>, your transcription output path is\n                        <code>s3://DOC-EXAMPLE-BUCKET/test-files/my-transcript/my-first-transcription.json</code>.</p>\n            </li>\n         </ul>\n         <p>If you specify the name of an Amazon S3 bucket sub-folder that doesn't exist,\n            one is created for you.</p>"}))
    StartTranscriptionJobRequest.add_member(:output_encryption_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSKeyId, location_name: 'OutputEncryptionKMSKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key you want to use to encrypt your transcription\n            output.</p>\n         <p>If using a key located in the <b>current</b>\n            Amazon Web Services account, you can specify your KMS key in one of four\n            ways:</p>\n         <ol>\n            <li>\n               <p>Use the KMS key ID itself. For example,\n                        <code>1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use an alias for the KMS key ID. For example,\n                        <code>alias/ExampleAlias</code>.</p>\n            </li>\n            <li>\n               <p>Use the Amazon Resource Name (ARN) for the KMS key ID. For\n                    example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If using a key located in a <b>different</b>\n            Amazon Web Services account than the current Amazon Web Services account, you can specify\n            your KMS key in one of two ways:</p>\n         <ol>\n            <li>\n               <p>Use the ARN for the KMS key ID. For example,\n                        <code>arn:aws:kms:region:account-ID:key/1234abcd-12ab-34cd-56ef-1234567890ab</code>.</p>\n            </li>\n            <li>\n               <p>Use the ARN for the KMS key alias. For example,\n                        <code>arn:aws:kms:region:account-ID:alias/ExampleAlias</code>.</p>\n            </li>\n         </ol>\n         <p>If you do not specify an encryption key, your output is encrypted with the default\n                Amazon S3 key (SSE-S3).</p>\n         <p>If you specify a KMS key to encrypt your output, you must also specify\n            an output location using the <code>OutputLocation</code> parameter.</p>\n         <p>Note that the role making the  request must\n            have permission to use the specified KMS key.</p>"}))
    StartTranscriptionJobRequest.add_member(:kms_encryption_context, Smithy::Schema::Shapes::ShapeRef.new(shape: KMSEncryptionContextMap, location_name: 'KMSEncryptionContext', traits: {"smithy.api#documentation" => "<p>A map of plain text, non-secret key:value pairs, known as encryption context pairs,\n            that provide an added layer of security for your data. For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/key-management.html#kms-context\">KMS encryption context</a> and <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/symmetric-asymmetric.html\">Asymmetric keys in KMS</a>.</p>"}))
    StartTranscriptionJobRequest.add_member(:settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Settings, location_name: 'Settings', traits: {"smithy.api#documentation" => "<p>Specify additional optional settings in your  \n            request, including channel identification, alternative transcriptions, speaker\n            partitioning. You can use that to apply custom vocabularies and vocabulary filters.</p>\n         <p>If you want to include a custom vocabulary or a custom vocabulary filter (or both)\n            with your request but <b>do not</b> want to use automatic\n            language identification, use <code>Settings</code> with the <code>VocabularyName</code>\n            or <code>VocabularyFilterName</code> (or both) sub-parameter.</p>\n         <p>If you're using automatic language identification with your request and want to\n            include a custom language model, a custom vocabulary, or a custom vocabulary filter, use\n            instead the <code></code> parameter with the\n                <code>LanguageModelName</code>, <code>VocabularyName</code> or\n                <code>VocabularyFilterName</code> sub-parameters.</p>"}))
    StartTranscriptionJobRequest.add_member(:model_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: ModelSettings, location_name: 'ModelSettings', traits: {"smithy.api#documentation" => "<p>Specify the custom language model you want to include with your transcription job. If\n            you include <code>ModelSettings</code> in your request, you must include the\n                <code>LanguageModelName</code> sub-parameter.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/custom-language-models.html\">Custom language\n                models</a>.</p>"}))
    StartTranscriptionJobRequest.add_member(:job_execution_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: JobExecutionSettings, location_name: 'JobExecutionSettings', traits: {"smithy.api#documentation" => "<p>Makes it possible to control how your transcription job is processed. Currently, the\n            only <code>JobExecutionSettings</code> modification you can choose is enabling job\n            queueing using the <code>AllowDeferredExecution</code> sub-parameter.</p>\n         <p>If you include <code>JobExecutionSettings</code> in your request, you must also\n            include the sub-parameters: <code>AllowDeferredExecution</code> and\n                <code>DataAccessRoleArn</code>.</p>"}))
    StartTranscriptionJobRequest.add_member(:content_redaction, Smithy::Schema::Shapes::ShapeRef.new(shape: ContentRedaction, location_name: 'ContentRedaction', traits: {"smithy.api#documentation" => "<p>Makes it possible to redact or flag specified personally identifiable information (PII) in \n            your transcript. If you use <code>ContentRedaction</code>, you must also include the \n            sub-parameters: <code>RedactionOutput</code> and <code>RedactionType</code>. You can \n            optionally include <code>PiiEntityTypes</code> to choose which types of PII you want to redact.\n            If you do not include <code>PiiEntityTypes</code> in your request, all PII is redacted.</p>"}))
    StartTranscriptionJobRequest.add_member(:identify_language, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IdentifyLanguage', traits: {"smithy.api#documentation" => "<p>Enables automatic language identification in your transcription job request. Use this\n            parameter if your media file contains only one language. If your media contains multiple\n            languages, use <code>IdentifyMultipleLanguages</code> instead.</p>\n         <p>If you include <code>IdentifyLanguage</code>, you can optionally include a list of\n            language codes, using <code>LanguageOptions</code>, that you think may be present in\n            your media file. Including <code>LanguageOptions</code> restricts\n                <code>IdentifyLanguage</code> to only the language options that you specify, which\n            can improve transcription accuracy.</p>\n         <p>If you want to apply a custom language model, a custom vocabulary, or a custom\n            vocabulary filter to your automatic language identification request, include\n                <code>LanguageIdSettings</code> with the relevant sub-parameters\n                (<code>VocabularyName</code>, <code>LanguageModelName</code>, and\n                <code>VocabularyFilterName</code>). If you include <code>LanguageIdSettings</code>,\n            also include <code>LanguageOptions</code>.</p>\n         <p>Note that you must include one of <code>LanguageCode</code>,\n                <code>IdentifyLanguage</code>, or <code>IdentifyMultipleLanguages</code> in your\n            request. If you include more than one of these parameters, your transcription job\n            fails.</p>"}))
    StartTranscriptionJobRequest.add_member(:identify_multiple_languages, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IdentifyMultipleLanguages', traits: {"smithy.api#documentation" => "<p>Enables automatic multi-language identification in your transcription job request. Use\n            this parameter if your media file contains more than one language. If your media\n            contains only one language, use <code>IdentifyLanguage</code> instead.</p>\n         <p>If you include <code>IdentifyMultipleLanguages</code>, you can optionally include a\n            list of language codes, using <code>LanguageOptions</code>, that you think may be\n            present in your media file. Including <code>LanguageOptions</code> restricts\n                <code>IdentifyLanguage</code> to only the language options that you specify, which\n            can improve transcription accuracy.</p>\n         <p>If you want to apply a custom vocabulary or a custom vocabulary filter to your\n            automatic language identification request, include <code>LanguageIdSettings</code> with\n            the relevant sub-parameters (<code>VocabularyName</code> and\n                <code>VocabularyFilterName</code>). If you include <code>LanguageIdSettings</code>,\n            also include <code>LanguageOptions</code>.</p>\n         <p>Note that you must include one of <code>LanguageCode</code>,\n                <code>IdentifyLanguage</code>, or <code>IdentifyMultipleLanguages</code> in your\n            request. If you include more than one of these parameters, your transcription job\n            fails.</p>"}))
    StartTranscriptionJobRequest.add_member(:language_options, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageOptions, location_name: 'LanguageOptions', traits: {"smithy.api#documentation" => "<p>You can specify two or more language codes that represent the languages you think may\n            be present in your media. Including more than five is not recommended. If you're unsure\n            what languages are present, do not include this parameter.</p>\n         <p>If you include <code>LanguageOptions</code> in your request, you must also include\n                <code>IdentifyLanguage</code>.</p>\n         <p>For more information, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/supported-languages.html\">Supported\n            languages</a>.</p>\n         <p>To transcribe speech in Modern Standard Arabic (<code>ar-SA</code>)in Amazon Web Services GovCloud (US) (US-West, us-gov-west-1), Amazon Web Services GovCloud (US) (US-East, us-gov-east-1), in Canada (Calgary) ca-west-1 and Africa (Cape Town) af-south-1, your media file\n            must be encoded at a sample rate of 16,000 Hz or higher.</p>"}))
    StartTranscriptionJobRequest.add_member(:subtitles, Smithy::Schema::Shapes::ShapeRef.new(shape: Subtitles, location_name: 'Subtitles', traits: {"smithy.api#documentation" => "<p>Produces subtitle files for your input media. You can specify WebVTT (*.vtt) and\n            SubRip (*.srt) formats.</p>"}))
    StartTranscriptionJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Adds one or more custom tags, each in the form of a key:value pair, to a new\n            transcription job at the time you start this new job.</p>\n         <p>To learn more about using tags with Amazon Transcribe, refer to <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tagging.html\">Tagging\n                resources</a>.</p>"}))
    StartTranscriptionJobRequest.add_member(:language_id_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: LanguageIdSettingsMap, location_name: 'LanguageIdSettings', traits: {"smithy.api#documentation" => "<p>If using automatic language identification in your request and you want to apply a\n            custom language model, a custom vocabulary, or a custom vocabulary filter, include\n                <code>LanguageIdSettings</code> with the relevant sub-parameters\n                (<code>VocabularyName</code>, <code>LanguageModelName</code>, and\n                <code>VocabularyFilterName</code>). Note that multi-language identification\n                (<code>IdentifyMultipleLanguages</code>) doesn't support custom language\n            models.</p>\n         <p>\n            <code>LanguageIdSettings</code> supports two to five language codes. Each language\n            code you include can have an associated custom language model, custom vocabulary, and\n            custom vocabulary filter. The language codes that you specify must match the languages\n            of the associated custom language models, custom vocabularies, and custom vocabulary\n            filters.</p>\n         <p>It's recommended that you include <code>LanguageOptions</code> when using\n                <code>LanguageIdSettings</code> to ensure that the correct language dialect is\n            identified. For example, if you specify a custom vocabulary that is in\n                <code>en-US</code> but Amazon Transcribe determines that the language spoken in\n            your media is <code>en-AU</code>, your custom vocabulary <i>is not</i>\n            applied to your transcription. If you include <code>LanguageOptions</code> and include\n                <code>en-US</code> as the only English language dialect, your custom vocabulary\n                <i>is</i> applied to your transcription.</p>\n         <p>If you want to include a custom language model with your request but <b>do not</b> want to use automatic language identification, use\n            instead the <code></code> parameter with the\n                <code>LanguageModelName</code> sub-parameter. If you want to include a custom\n            vocabulary or a custom vocabulary filter (or both) with your request but <b>do not</b> want to use automatic language identification, use\n            instead the <code></code> parameter with the\n                <code>VocabularyName</code> or <code>VocabularyFilterName</code> (or both)\n            sub-parameter.</p>"}))
    StartTranscriptionJobRequest.add_member(:toxicity_detection, Smithy::Schema::Shapes::ShapeRef.new(shape: ToxicityDetection, location_name: 'ToxicityDetection', traits: {"smithy.api#documentation" => "<p>Enables toxic speech detection in your transcript. If you include \n            <code>ToxicityDetection</code> in your request, you must also include\n            <code>ToxicityCategories</code>.</p>\n         <p>For information on the types of toxic speech Amazon Transcribe can detect, see \n            <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/toxic-language.html\">Detecting toxic\n                speech</a>.</p>"}))
    StartTranscriptionJobRequest.type = Types::StartTranscriptionJobRequest
    StartTranscriptionJobResponse.add_member(:transcription_job, Smithy::Schema::Shapes::ShapeRef.new(shape: TranscriptionJob, location_name: 'TranscriptionJob', traits: {"smithy.api#documentation" => "<p>Provides detailed information about the current transcription job, including job\n            status and, if applicable, failure reason.</p>"}))
    StartTranscriptionJobResponse.type = Types::StartTranscriptionJobResponse
    StringTargetList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: NonEmptyString)
    SubtitleFileUris.member = Smithy::Schema::Shapes::ShapeRef.new(shape: Uri)
    SubtitleFormat.add_member(:vtt, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VTT', traits: {"smithy.api#enumValue" => "vtt"}))
    SubtitleFormat.add_member(:srt, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SRT', traits: {"smithy.api#enumValue" => "srt"}))
    SubtitleFormats.member = Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleFormat)
    Subtitles.add_member(:formats, Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleFormats, location_name: 'Formats', traits: {"smithy.api#documentation" => "<p>Specify the output format for your subtitle file; if you select both WebVTT\n                (<code>vtt</code>) and SubRip (<code>srt</code>) formats, two output files are\n            generated.</p>"}))
    Subtitles.add_member(:output_start_index, Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleOutputStartIndex, location_name: 'OutputStartIndex', traits: {"smithy.api#documentation" => "<p>Specify the starting value that is assigned to the first subtitle segment.</p>\n         <p>The default start index for Amazon Transcribe is <code>0</code>, which differs from\n            the more widely used standard of <code>1</code>. If you're uncertain which value to use,\n            we recommend choosing <code>1</code>, as this may improve compatibility with other\n            services.</p>"}))
    Subtitles.type = Types::Subtitles
    SubtitlesOutput.add_member(:formats, Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleFormats, location_name: 'Formats', traits: {"smithy.api#documentation" => "<p>Provides the format of your subtitle files. If your request included both WebVTT\n                (<code>vtt</code>) and SubRip (<code>srt</code>) formats, both formats are\n            shown.</p>"}))
    SubtitlesOutput.add_member(:subtitle_file_uris, Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleFileUris, location_name: 'SubtitleFileUris', traits: {"smithy.api#documentation" => "<p>The Amazon S3 location of your transcript. You can use this URI to access or\n            download your subtitle file. Your subtitle file is stored in the same location as your\n            transcript. If you specified both WebVTT and SubRip subtitle formats, two URIs are\n            provided.</p>\n         <p>If you included <code>OutputBucketName</code> in your transcription job request, this\n            is the URI of that bucket. If you also included <code>OutputKey</code> in your request,\n            your output is located in the path you specified in your request.</p>\n         <p>If you didn't include <code>OutputBucketName</code> in your transcription job request,\n            your subtitle file is stored in a service-managed bucket, and\n                <code>TranscriptFileUri</code> provides you with a temporary URI you can use for\n            secure access to your subtitle file.</p>\n         <note>\n            <p>Temporary URIs for service-managed Amazon S3 buckets are only valid for 15\n                minutes. If you get an <code>AccesDenied</code> error, you can get a new temporary\n                URI by running a <code>GetTranscriptionJob</code> or\n                    <code>ListTranscriptionJob</code> request.</p>\n         </note>"}))
    SubtitlesOutput.add_member(:output_start_index, Smithy::Schema::Shapes::ShapeRef.new(shape: SubtitleOutputStartIndex, location_name: 'OutputStartIndex', traits: {"smithy.api#documentation" => "<p>Provides the start index value for your subtitle files. If you did not specify a value\n            in your request, the default value of <code>0</code> is used.</p>"}))
    SubtitlesOutput.type = Types::SubtitlesOutput
    Summarization.add_member(:generate_abstractive_summary, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'GenerateAbstractiveSummary', traits: {"smithy.api#documentation" => "<p>Enables Generative call summarization in your Call Analytics request</p>\n         <p>Generative call summarization provides a summary of the transcript including important\n\t    components discussed in the conversation.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/transcribe/latest/dg/tca-enable-summarization.html\">Enabling generative call \n\t        summarization</a>.</p>", "smithy.api#required" => {}}))
    Summarization.type = Types::Summarization
    Tag.add_member(:key, Smithy::Schema::Shapes::ShapeRef.new(shape: TagKey, location_name: 'Key', traits: {"smithy.api#documentation" => "<p>The first part of a key:value pair that forms a tag associated with a given resource.\n            For example, in the tag <code>Department:Sales</code>, the key is 'Department'.</p>", "smithy.api#required" => {}}))
    Tag.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: TagValue, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>The second part of a key:value pair that forms a tag associated with a given resource.\n            For example, in the tag <code>Department:Sales</code>, the value is 'Sales'.</p>\n         <p>Note that you can set the value of a tag to an empty string, but you can't set the\n            value of a tag to null. Omitting the tag value is the same as using an empty\n            string.</p>", "smithy.api#required" => {}}))
    Tag.type = Types::Tag
    TagKeyList.member = Smithy::Schema::Shapes::ShapeRef.new(shape: TagKey)
